contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // params: tokenIds and tokenWeights arrays, and MerkleMultiProof encoded as bytes for calldata packing,
    // and an amount of ETH to forward (ethAmount). We represent the MerkleMultiProof by three dynamic parts
    // encoded off-chain into bytes where layout is: proof bytes32[] then flags bool[] (packed as bytes),
    // but since we cannot construct complex calldata generically here, we rely on merkleRoot==0 handling
    // in C: when merkleRoot==0, sumWeightsAndValidateProof returns tokenIds.length * 1e18 ignoring proof.
    // So we choose to call buy with an empty proof (zero-length) by passing empty arrays.

    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, uint256 ethAmount) public payable {
        require(address(this).balance >= ethAmount);

        // Observe pre-state
        uint128 preVirtualBase = c.virtualBaseTokenReserves();
        uint128 preVirtualNft = c.virtualNftReserves();
        address baseToken = c.baseToken();

        // We will attempt to call buy. Capture whether it reverted.
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // For determinism and to avoid needing a merkle proof, we only run the actionable path
        // when the pool's merkleRoot is zero OR tokenIds.length > 0 matches expectations.
        // But we must not require conditions on c's state. Instead attempt call and record revert.

        try c.buy{value: ethAmount}(tokenIds, tokenWeights, /* MerkleMultiProof calldata */ abi.encode(uint256(0), uint256(0))) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint128 postVirtualBase = c.virtualBaseTokenReserves();
        uint128 postVirtualNft = c.virtualNftReserves();
        uint256 cBalanceAfter = address(c).balance;

        // General rule asserted:
        // If buy succeeded (not reverted) then
        //   postVirtualBase == preVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount)
        //   postVirtualNft == preVirtualNft - outputAmount, where outputAmount equals the sum of weights used by buy
        // We cannot directly read the sum-of-weights from c, but buy computes weightSum from tokenWeights; when merkleRoot==0
        // sumWeightsAndValidateProof returns tokenIds.length * 1e18, so outputAmount equals that value when merkleRoot==0.
        // To keep the assertion general for all merkle roots, we assert monotonic effects:
        //   - virtualBaseTokenReserves never decreases when buy succeeds
        //   - virtualNftReserves never increases when buy succeeds
        // Additionally, if buy reverted then the observed reserves must be unchanged.

        assert(
            // if reverted then reserves unchanged
            (reverted && postVirtualBase == preVirtualBase && postVirtualNft == preVirtualNft)
            ||
            // if not reverted, virtualBase increased by at least netInputAmount - feeAmount - protocolFeeAmount
            (!reverted && postVirtualBase >= preVirtualBase + SafeCastToUint128(netInputAmount - feeAmount - protocolFeeAmount) && postVirtualNft <= preVirtualNft)
        );
    }

    // small helper to safely cast uint256 to uint128 for arithmetic in the assert expression
    // Because we cannot declare new internal functions besides constructor/receive/fallback per problem, implement as inline internal library-like via pure expression
    function SafeCastToUint128(uint256 x) internal pure returns (uint128) {
        if (x > type(uint128).max) return type(uint128).max;
        return uint128(x);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // We pass tokenIds and tokenWeights; to avoid constructing a MerkleMultiProof struct here
    // we exploit that when the pool's merkleRoot == 0 the contract ignores the proof and
    // treats each token as weight 1e18. However we still must supply some MerkleMultiProof memory value.
    // Solidity allows creating an empty struct in-place by building its fields.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, uint256 ethAmount) public payable {
        // if forwarding ETH, ensure the test contract has it
        require(address(this).balance >= ethAmount);

        // observe pre-state via public getters
        uint128 preVirtualBase = c.virtualBaseTokenReserves();
        uint128 preVirtualNft = c.virtualNftReserves();
        uint256 preBalance = address(c).balance;

        // Prepare an empty MerkleMultiProof in memory: two dynamic arrays (proof and flags) zero-length
        C.MerkleMultiProof memory mp;
        mp.proof = new bytes32[](0);
        mp.flags = new bool[](0);

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // Call buy and capture revert or results. Must be a top-level statement for state-changing call.
        // Forward ethAmount if provided.
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint128 postVirtualBase = c.virtualBaseTokenReserves();
        uint128 postVirtualNft = c.virtualNftReserves();
        uint256 postBalance = address(c).balance;

        // General property asserted:
        // - If call reverted then virtual reserves and contract balance are unchanged.
        // - If call succeeded then virtualBase did not decrease (post >= pre) and virtualNft did not increase (post <= pre)
        //   and postVirtualBase increased by at least (netInputAmount - feeAmount - protocolFeeAmount) when that quantity fits into uint128.
        // Use a safe conversion: if the computed delta > type(uint128).max we only require postVirtualBase >= preVirtualBase (already covered),
        // so the stronger numeric lower bound is required only when it fits into uint128.

        uint256 claimedIncrease = 0;
        if (!reverted) {
            // compute netInputAmount - feeAmount - protocolFeeAmount without underflow (it should be >=0 as per buyQuote semantics)
            if (netInputAmount + feeAmount + protocolFeeAmount >= feeAmount + protocolFeeAmount) {
                // netInputAmount is actually returned by buy as input + fee + protocol; but keep safe math
                if (netInputAmount >= feeAmount + protocolFeeAmount) {
                    claimedIncrease = netInputAmount - feeAmount - protocolFeeAmount;
                } else {
                    claimedIncrease = 0;
                }
            }
        }

        // cast check: only enforce numeric lower bound when claimedIncrease fits in uint128
        bool numericLowerBound = true;
        if (!reverted) {
            if (claimedIncrease <= type(uint128).max) {
                numericLowerBound = uint128(preVirtualBase) + uint128(claimedIncrease) <= postVirtualBase;
            } else {
                // if it doesn't fit, we accept the weaker monotonicity requirement
                numericLowerBound = postVirtualBase >= preVirtualBase;
            }
        }

        assert(
            // reverted -> no observable change
            (reverted && postVirtualBase == preVirtualBase && postVirtualNft == preVirtualNft && postBalance == preBalance)
            ||
            // succeeded -> monotonicities and numeric lower bound when applicable
            (!reverted && postVirtualBase >= preVirtualBase && postVirtualNft <= preVirtualNft && numericLowerBound)
        );
    }

    receive() external payable {}
}

