contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // params: tokenIds to deposit, and baseTokenAmount to send as ETH when baseToken==address(0)
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount) public payable {
        // ensure the test contract has enough ETH to forward if needed
        require(address(this).balance >= baseTokenAmount, "insufficient balance for test");

        // Read whether pool expects native ETH (baseToken == address(0)) before call
        address poolBaseToken = c.baseToken();

        // record balance before
        uint256 before = address(c).balance;

        bool reverted = false;
        // perform deposit: when pool expects ETH we must send baseTokenAmount, else we must not send ETH
        if (poolBaseToken == address(0)) {
            // call depositing ETH
            try c.deposit{value: baseTokenAmount}(tokenIds, baseTokenAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // when pool expects ERC20, sending ETH should revert due to InvalidEthAmount; call without value
            try c.deposit(tokenIds, baseTokenAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 after = address(c).balance;

        // General rule asserted:
        // - If pool.baseToken == address(0): deposit call should not revert and contract balance increases by exactly baseTokenAmount.
        // - If pool.baseToken != address(0): calling deposit without sending ETH should not change pool ETH balance (increase == 0).
        // The assert encodes both cases using only public observations.
        assert(
            (poolBaseToken == address(0) && reverted == false && after == before + baseTokenAmount)
            ||
            (poolBaseToken != address(0) && after == before)
        );
    }

    receive() external payable {}
}

