contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // params: tokenIds array and baseTokenAmount and a flag indicating whether we will send ETH
    // The function is payable so it can forward ETH to c.deposit
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, bool sendEth) public payable {
        require(msg.sender != address(0)); // simple noop precondition to allow calldata usage

        // Read prior observable state
        address poolAddr = address(c);
        uint256 beforeBalance = poolAddr.balance;
        address baseToken = c.baseToken(); // public getter

        bool reverted = false;
        // If we plan to send ETH, ensure this contract has enough balance
        uint256 sendAmount = sendEth ? baseTokenAmount : 0;
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount, "Insufficient test balance");
        }

        // Make the state-changing call as top-level statement
        try c.deposit{value: sendAmount}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call observable values
        uint256 afterBalance = poolAddr.balance;

        // General rule (single assert):
        // - If the pool's baseToken getter is address(0) then deposit must not revert when we sent exactly baseTokenAmount wei,
        //   and the pool's balance increases by exactly baseTokenAmount.
        // - If the pool's baseToken getter is not address(0) then sending any ETH (sendEth==true and sendAmount>0) must cause deposit to revert,
        //   and in that case the pool balance must be unchanged. If no ETH was sent, deposit may succeed or revert depending on other conditions;
        //   we do not constrain that case here.
        assert(
            (baseToken == address(0) ? (reverted == false && afterBalance == beforeBalance + sendAmount) : (sendAmount == 0 ? true : (reverted == true && afterBalance == beforeBalance)))
        );
    }

    // Allow contract to hold ETH for tests
    receive() external payable {}
}

