contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test the relation between buyQuote values and state changes when buy succeeds.
    // Parameters:
    // - tokenIds and tokenWeights are passed to sumWeightsAndValidateProof/buy; we avoid Merkle by ensuring pool has merkleRoot==0 by calling setMerkleRoot via factory-owned flow is impossible here,
    // so we only call when merkleRoot == 0 implicitly by using empty arrays (the contract treats merkleRoot==0 as default).
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, uint256 ethToSend) public payable {
        // precondition: tokenIds.length == tokenWeights.length and non-empty to make meaningful buy
        require(tokenIds.length == tokenWeights.length && tokenIds.length > 0);

        // Ensure we have enough balance to forward ETH if needed
        if (ethToSend > 0) require(address(this).balance >= ethToSend);

        // Read pre-state virtual reserves and factory protocol fee rate
        uint128 vb_before = c.virtualBaseTokenReserves();
        uint128 vn_before = c.virtualNftReserves();

        // Compute weightSum using public helper (matching internal logic when merkleRoot==0)
        // We call sumWeightsAndValidateProof with empty proof to get the weight sum; since merkleRoot may be non-zero, this could revert.
        bool sumReverted = false;
        uint256 weightSum = 0;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0))) returns (uint256 w) {
            weightSum = w;
        } catch {
            sumReverted = true;
        }

        // If proof validation failed, buy would revert; capture that and assert consistency: when sumWeightsAndValidateProof reverts, buy must revert too.
        bool buyReverted = false;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        if (!sumReverted) {
            // Query buyQuote (view)
            (uint256 qNetInput, uint256 qFee, uint256 qProtocol) = c.buyQuote(weightSum);

            // Attempt to call buy with msg.value = ethToSend if baseToken==address(0)
            // Must ensure we call top-level state-changing call directly.
            try c.buy{value: ethToSend}(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0))) returns (uint256 n, uint256 f, uint256 p) {
                netInputAmount = n;
                feeAmount = f;
                protocolFeeAmount = p;
            } catch {
                buyReverted = true;
            }

            // Read post-state reserves
            uint128 vb_after = c.virtualBaseTokenReserves();
            uint128 vn_after = c.virtualNftReserves();

            // General rule to assert:
            // If buy did NOT revert then:
            //  - virtualNftReserves decreases by exactly weightSum
            //  - virtualBaseTokenReserves increases by at least (netInputAmount - feeAmount - protocolFeeAmount)
            // If buy reverted then sum must have been valid but buy still reverted (we assert nothing else). We combine into one boolean expression.
            assert((!buyReverted && vn_after + uint128(weightSum) == vn_before && vb_after >= vb_before + uint128(netInputAmount - feeAmount - protocolFeeAmount)) || (buyReverted && !sumReverted));

        } else {
            // sumWeightsAndValidateProof reverted: then buy must revert as well (we assert that calling buy reverts)
            try c.buy{value: ethToSend}(tokenIds, tokenWeights, C.MerkleMultiProof(new bytes32[](0), new bool[](0))) returns (uint256, uint256, uint256) {
                // if buy succeeded despite sum reverting earlier somehow, that's a violation
                assert(false);
            } catch {
                // both reverted: ok — satisfy single assert by asserting true
                assert(true == true);
            }
        }
    }

    receive() external payable {}
}

