        // to derive weightSum and then call buy with a MerkleMultiProof constructed inline via abi encoding

        // require we have enough balance in this contract to forward ETH if needed
        require(address(this).balance >= ethValue, "insufficient balance for forwarded ETH");

        // Read pre-state observable values
        uint128 preVirtualBase = c.virtualBaseTokenReserves();
        uint128 preVirtualNft = c.virtualNftReserves();
        address baseToken = c.baseToken();

        // Build MerkleMultiProof in memory to pass to buy. Solidity doesn't allow constructing a struct with dynamic calldata directly,
        // but we can abi.encode to create calldata and use low-level call to invoke buy. However constraint forbids interacting except via c's external surface.
        // Instead, we will call c.sumWeightsAndValidateProof to determine whether provided proof is valid; that function is public view and takes the MerkleMultiProof struct.
        // To call it we need to create the struct in memory and pass. Solidity allows that for memory structs.

        C.MerkleMultiProof memory mm;
        mm.proof = proof;
        mm.flags = flags;

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // Try calling buy and capture revert status and outputs.
        try c.buy{value: ethValue}(tokenIds, tokenWeights, mm) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Read post-state observable values
        uint128 postVirtualBase = c.virtualBaseTokenReserves();
        uint128 postVirtualNft = c.virtualNftReserves();

        // Characterize valid execution: if not reverted then
        //  - postVirtualNft == preVirtualNft - weightSum
        //  - postVirtualBase == preVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount)
        // If reverted then either the merkle proof was invalid (sumWeightsAndValidateProof would revert) OR there was an ETH mismatch

        // Compute weightSum via public view function sumWeightsAndValidateProof; this will revert if proof invalid.
        uint256 weightSum;
        bool proofValid;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mm) returns (uint256 s) {
            proofValid = true;
            weightSum = s;
        } catch {
            proofValid = false;
            weightSum = 0;
        }

        // Now assert the general rule combining both cases.
        // If the buy call succeeded then proof must have been valid and reserves must have changed consistently with buy's logic.
        // If the buy call reverted then either proof was invalid or there was an ETH amount mismatch depending on baseToken.
        if (!reverted) {
            // invariant: proof was valid
            // Also avoid underflow in expression by comparing using >= where appropriate
            assert(proofValid);
            // The contract updates: virtualNftReserves decreased by weightSum
            assert(uint256(preVirtualNft) == uint256(postVirtualNft) + weightSum || uint256(postVirtualNft) + weightSum == uint256(preVirtualNft));
            // The contract increases virtualBaseTokenReserves by (netInputAmount - feeAmount - protocolFeeAmount)
            uint256 deltaBase = uint256(postVirtualBase) - uint256(preVirtualBase);
            uint256 expectedIncrease = netInputAmount - feeAmount - protocolFeeAmount;
            assert(deltaBase == expectedIncrease);
        } else {
            // If reverted then either proof invalid OR ETH mismatch occurred (for baseToken==address(0) msg.value handling or baseToken != address(0) with msg.value>0)
            if (!proofValid) {
                // ok: reverted due to invalid merkle
                assert(true);
            } else {
                // proof valid but buy reverted: must be due to ETH/token mismatch
                if (baseToken == address(0)) {
                    // For ETH pool, buy requires msg.value >= netInputAmount. We don't have netInputAmount because call reverted,
                    // but the only allowed reason besides invalid proof is InvalidEthAmount; assert that ethValue != 0 would be consistent (we cannot know exact required amount), so require ethValue >= 0 trivially true.
                    assert(true);
                } else {
                    // For ERC20 base token, buy reverts if msg.value > 0. So if proof valid and reverted then msg.value must have been > 0
                    assert(ethValue > 0);
                }
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
