    // Single public entrypoint: drives C.buy and asserts the described general rule.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethValue) public payable {
        require(address(this).balance >= ethValue, "insufficient balance to forward ETH");

        // Read pre-state observables
        uint128 preVirtualBase = c.virtualBaseTokenReserves();
        uint128 preVirtualNft = c.virtualNftReserves();
        address baseToken = c.baseToken();

        // construct MerkleMultiProof in memory to pass to calls
        C.MerkleMultiProof memory mm;
        mm.proof = proof;
        mm.flags = flags;

        // Attempt to call sumWeightsAndValidateProof (view) to determine proof validity and weightSum
        bool proofValid;
        uint256 weightSum;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mm) returns (uint256 s) {
            proofValid = true;
            weightSum = s;
        } catch {
            proofValid = false;
            weightSum = 0;
        }

        // Attempt the state-changing buy call and capture whether it reverted and returned values
        bool buyReverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: ethValue}(tokenIds, tokenWeights, mm) returns (uint256 n, uint256 f, uint256 p) {
            buyReverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
