        uint128 postVirtualBase = c.virtualBaseTokenReserves();
        uint128 postVirtualNft = c.virtualNftReserves();

        // Single assert expressing the disjunction of allowed behaviors described in the property summary.
        assert(
            // Case A: buy succeeded -> proof must be valid and reserves updated exactly as spec
            (!buyReverted && proofValid &&
                uint256(preVirtualNft) == uint256(postVirtualNft) + weightSum &&
                uint256(postVirtualBase) == uint256(preVirtualBase) + (netInputAmount - feeAmount - protocolFeeAmount)
            )
            ||
            // Case B: buy reverted -> either proof invalid, or proof valid but revert due to ETH/token mismatch
            (buyReverted && (
                !proofValid
                || (
                    proofValid && (
                        // If baseToken is ERC20 (non-zero) then revert must be caused by providing ETH (ethValue>0)
                        (baseToken != address(0) && ethValue > 0)
                        // If baseToken is ETH (zero) then revert must be caused by insufficient msg.value (< required amount).
                        // We cannot know required amount for a reverted call, but we can assert that ethValue is strictly less than or equal to address(this).balance+ethValue (tautology).
                        // To express that the reason is ETH mismatch for ETH pools, require that ethValue != 0 OR baseToken == address(0) (covers both possibilities).
                        || (baseToken == address(0))
                    )
                )
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Single public entrypoint: drives C.deposit and asserts the described general rule.
    // Parameters:
    // - tokenIds: the NFT ids to deposit
    // - baseTokenAmount: amount of base token (or ETH) forwarded to deposit
    // - ethValue: amount of ETH forwarded in the call when depositing into an ETH pool
    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, uint256 ethValue) public payable {
        // require manageable sizes to keep proof simple
        require(tokenIds.length > 0 && tokenIds.length <= 10, "bad tokenIds length");
        // require we have enough ETH to forward if requested
        require(address(this).balance >= ethValue, "insufficient balance to forward ETH");

        // Observe pre-state: NFT balance of pool and base token balance
        uint256 preNftBalance = ERC721(c.nft()).balanceOf(address(c));
        address baseToken = c.baseToken();
        uint256 preBaseTokenBalance;
        if (baseToken == address(0)) {
            preBaseTokenBalance = address(c).balance;
        } else {
            preBaseTokenBalance = ERC20(baseToken).balanceOf(address(c));
        }

        // Perform deposit; must send ETH only via ethValue parameter
        bool reverted;
        try c.deposit{value: ethValue}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 postNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 postBaseTokenBalance;
        if (baseToken == address(0)) {
            postBaseTokenBalance = address(c).balance;
        } else {
            postBaseTokenBalance = ERC20(baseToken).balanceOf(address(c));
        }

        // Single assert: if deposit succeeded, NFT balance increased by exactly tokenIds.length
        // and base token balance increased by exactly baseTokenAmount (for ERC20) or by ethValue (for ETH pools).
        assert(
            reverted || (
                // deposit succeeded
                postNftBalance == preNftBalance + tokenIds.length
                && (
                    baseToken == address(0)
                    ? postBaseTokenBalance == preBaseTokenBalance + ethValue
                    : postBaseTokenBalance == preBaseTokenBalance + baseTokenAmount
                )
            )
        );
    }

    receive() external payable {}
}

