        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof) returns (uint256 s) {
            weightSum = s;
            sumReverted = false;
        } catch {
            weightSum = 0;
            sumReverted = true;
        }

        // Compute quote only if sum succeeded
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        if (!sumReverted) {
            (netInputAmount, feeAmount, protocolFeeAmount) = c.buyQuote(weightSum);
        }

        // Ensure this contract holds enough ETH to send if needed
        if (address(this).balance < ethAmount) {
            // try to fail early in a way the checker can satisfy by providing ETH
            // but don't revert the whole test; simply bound ethAmount
            ethAmount = address(this).balance;
        }

