contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        bytes32[] calldata proofBytes,
        bool[] calldata flags,
        uint256 ethAmount
    ) public payable {
        // basic shape requirements
        require(tokenIds.length == tokenWeights.length, "len");
        require(tokenIds.length > 0, "nonempty");

        // Build MerkleMultiProof in memory (ABI-compatible struct)
        C.MerkleMultiProof memory proof;
        proof.proof = proofBytes;
        proof.flags = flags;

        // Read reserves before
        uint256 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint256 beforeVirtualNft = c.virtualNftReserves();

        // Call sumWeightsAndValidateProof at top-level and capture revert via try/catch
        bool sumReverted;
        uint256 weightSum;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof) returns (uint256 s) {
            sumReverted = false;
            weightSum = s;
        } catch {
            sumReverted = true;
            weightSum = 0;
        }

        // If sum succeeded obtain buyQuote (view)
        uint256 quotedNetInput;
        uint256 quotedFee;
        uint256 quotedProtocolFee;
        if (!sumReverted) {
            (quotedNetInput, quotedFee, quotedProtocolFee) = c.buyQuote(weightSum);
        }

        // Ensure this contract has enough ETH to send if requested by test param
        if (address(this).balance < ethAmount) {
            ethAmount = address(this).balance;
        }

        // Attempt the buy call as a top-level try/catch and capture whether it reverted and returned values
        bool buyReverted;
        uint256 returnedNetInput;
        uint256 returnedFee;
        uint256 returnedProtocolFee;
        if (!sumReverted) {
            try c.buy{value: ethAmount}(tokenIds, tokenWeights, proof) returns (uint256 n, uint256 f, uint256 p) {
                buyReverted = false;
                returnedNetInput = n;
                returnedFee = f;
                returnedProtocolFee = p;
            } catch {
                buyReverted = true;
                returnedNetInput = 0;
                returnedFee = 0;
                returnedProtocolFee = 0;
            }
        } else {
            // If sum failed then we don't call buy; treat as reverted for the property
            buyReverted = true;
            returnedNetInput = 0;
            returnedFee = 0;
            returnedProtocolFee = 0;
        }

        // Read reserves after (view calls)
        uint256 afterVirtualBase = c.virtualBaseTokenReserves();
        uint256 afterVirtualNft = c.virtualNftReserves();

        // General invariant: if sum succeeded and buy did not revert then
        // - virtualNftReserves decreased exactly by weightSum
        // - virtualBaseTokenReserves increased by at least (returnedNetInput - returnedFee - returnedProtocolFee)
        assert(
            sumReverted || buyReverted || (
                // exact decrease in NFT reserves
                afterVirtualNft + weightSum == beforeVirtualNft
                // base reserves increased by at least netInput - fee - protocolFee
                && afterVirtualBase >= beforeVirtualBase + (returnedNetInput - returnedFee - returnedProtocolFee)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: tokenIds and tokenWeights arrays (as calldata can't be used here, use memory),
    // merkle proof components for buy (proof.proof and proof.flags), and an amount of ETH to send when baseToken==address(0)
    function run(uint256[] memory tokenIds, uint256[] memory tokenWeights, bytes32[] memory proofBytes, bool[] memory proofFlags, uint256 ethSend) public payable {
        require(tokenIds.length == tokenWeights.length, "len mismatch");
        // build MerkleMultiProof struct in memory
        C.MerkleMultiProof memory proof = C.MerkleMultiProof({ proof: proofBytes, flags: proofFlags });

        // Observe current baseToken to decide ETH vs ERC20 mode via public getter
        address base = c.baseToken();

        // Compute weight sum as sumWeightsAndValidateProof would (we can call buyQuote which takes the outputAmount)
        // But buyQuote expects outputAmount (weightSum). We'll conservatively compute a sum here for use in quote call.
        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }

        // Call buyQuote (view) to get expected amounts; view call allowed
        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(weightSum);

        // Precondition: the buyQuote's netInputAmount should be at least fee+protocolFee by formula in contract
        // (This is a general numeric relationship we assert later.)

        // Now attempt to perform buy. For ETH mode, we must send ethSend; require this contract has balance >= ethSend
        if (base == address(0)) {
            require(address(this).balance >= ethSend, "insufficient test ETH");
        }

        bool reverted;
        // Make the state-changing call as top-level statement
        try c.buy{value: base == address(0) ? ethSend : 0}(tokenIds, tokenWeights, proof) returns (uint256 a, uint256 b, uint256 d) {
            reverted = false;
            // We don't use returned values here further; they are captured for assert expression optionally
            netInputAmount = a;
            feeAmount = b;
            protocolFeeAmount = d;
        } catch {
            reverted = true;
        }

        // The general rule to assert:
        // 1) For any input, buyQuote(weightSum) returns netInputAmount >= feeAmount + protocolFeeAmount (i.e., netInputAmount - fee - protocol >= 0)
        // 2) If baseToken is ETH (address(0)) and the call did NOT revert, then the ethSend provided must be >= netInputAmount (otherwise contract would revert for insufficient ETH).
        // We express both in a single assertion over observed values and revert flag.

        // Note: avoid subtraction that can underflow inside assert by rewriting comparisons.
        // netInputAmount >= feeAmount + protocolFeeAmount  <=>  feeAmount + protocolFeeAmount <= netInputAmount
        // For ETH case: reverted == false implies ethSend >= netInputAmount

        assert(
            (feeAmount + protocolFeeAmount <= netInputAmount)
            && ( (base != address(0)) || reverted || ethSend >= netInputAmount )
        );
    }

    // allow receiving ETH for testing
    receive() external payable {}
}

