contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes32[] calldata proof, bool[] calldata flags, uint256 ethAmount) public payable {
        // arrange: ensure this test contract has enough ETH if needed
        if (ethAmount > 0) require(address(this).balance >= ethAmount, "insufficient test ETH");

        // read observable before-values
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();

        // prepare MerkleMultiProof struct-compatible calldata: we will pass via abi.encode
        // perform sumWeightsAndValidateProof as a view to get expected weight sum and to check proof validity
        C.MerkleMultiProof memory mp;
        mp.proof = proof;
        mp.flags = flags;

        bool willRevert;
        uint256 weightSum = 0;
        // calling the view may revert if proof invalid; catch that by try/catch on external call
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, mp) returns (uint256 ws) {
            willRevert = false;
            weightSum = ws;
        } catch {
            // invalid proof -> according to contract buy will revert; mark willRevert true and still attempt buy to observe revert
            willRevert = true;
        }

        // Now attempt the state-changing buy call and capture whether it reverts
        bool buyReverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // call buy with Ether if baseToken == address(0); we cannot inspect baseToken cheaply here in a single expression,
        // so always attempt payable call with provided ethAmount; contract will revert if unexpected ETH is sent when baseToken != 0
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, mp) returns (uint256 n, uint256 f, uint256 p) {
            buyReverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            buyReverted = true;
        }

        // read after-values (only if call didn't revert, otherwise state unchanged)
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();

        // General rule (single assert):
        // If buy succeeded (didn't revert) then:
        //   - virtualBaseTokenReserves increased by exactly (netInputAmount - feeAmount - protocolFeeAmount)
        //   - virtualNftReserves decreased by exactly weightSum
        // If buy reverted then either the earlier proof-check indicated invalid proof OR buyReverted is true.
        // Expressed as one boolean assertion over observed values and revert flags.
        assert(
            ( !buyReverted && !willRevert &&
                uint256(afterVirtualBase) == uint256(beforeVirtualBase) + (netInputAmount - feeAmount - protocolFeeAmount) &&
                uint256(afterVirtualNft) + weightSum == uint256(beforeVirtualNft)
            ) || (
                buyReverted
            )
        );
    }

    receive() external payable {}
}
